/// A mode change must animate even when reloading input views delivers an
/// immediate layout before the component's explicit animated update.
struct NagramiXExpandedPanelAnimation {
    enum Mode { case keyboard, emoji, formatting }
    private var mode: Mode?
    private var size: CGSize?

    mutating func resolve(mode: Mode, size: CGSize, transition: ComponentTransition, reduceMotion: Bool) -> ComponentTransition {
        let changesMode = self.mode != nil && self.mode != mode && self.size == size
        self.mode = mode
        self.size = size
        if reduceMotion { return .immediate }
        if changesMode && transition.animation.isImmediate { return .spring(duration: 0.4) }
        return transition
    }
}

/// Owns only a panel's outer presentation. Repeated layouts keep an ongoing
/// animation; a completion from an older dismissal cannot hide a newer panel.
final class NagramiXExpandedPanelPresentation {
    private var presented = false
    private var generation = 0
    private var size: CGSize?

    func update(view: UIView, frame: CGRect, size: CGSize, visible: Bool, transition: ComponentTransition, reduceMotion: Bool) {
        let resized = self.size != nil && self.size != size
        self.size = size
        let offscreen = CGRect(origin: CGPoint(x: frame.minX, y: size.height), size: frame.size)
        if reduceMotion || resized {
            self.generation += 1
            self.presented = visible
            view.layer.removeAnimation(forKey: "position")
            view.layer.removeAnimation(forKey: "bounds")
            view.layer.removeAnimation(forKey: "bounds.size")
            view.frame = visible ? frame : offscreen
            view.isHidden = !visible
            return
        }
        if visible {
            if !self.presented { self.generation += 1 }
            self.presented = true
            // A reversing dismissal already has a presentation position. Seeding
            // it at the bottom again would introduce a jump on rapid switches.
            if view.isHidden { ComponentTransition.immediate.setFrame(view: view, frame: offscreen) }
            view.isHidden = false
            transition.setFrame(view: view, frame: frame)
        } else if self.presented {
            self.presented = false
            self.generation += 1
            let generation = self.generation
            transition.setFrame(view: view, frame: offscreen, completion: { [weak self, weak view] completed in
                guard let self, completed, self.generation == generation, !self.presented else { return }
                view?.isHidden = true
            })
        }
    }
}

